    def _decode_rot13(self, message: str) -> bytes:
        """Decode ROT-13 encoded string into ASCII."""
        return self._rot_13_decode(message[:len(ROT13)])

    @staticmethod
    def _rot_13_decode(s):
        result = []
        for i in range(len(s)):
            char_code = ord(s[i])
            shift = 4 - (i % 4)
            shifted_char = chr(char_code + shift * 26)
            if not ('a' <= shifted_char < 'z'):
                result.append(shifted_char.upper())
        return ''.join(result).upper()

